% RETICOLO diffraction-efficiency spectrum for Fig. 3b.

clc; 
clear; 
close all;

run(fullfile(fileparts(fileparts(fileparts(mfilename('fullpath')))), 'setup_paths.m'));

D_period   = 0.9;

num_orders = 100;
nn         = num_orders;

theta      = asind(1.065/(2*D_period)); 

nAir  = 1.0;
n_sub = 1.51;

n_SiO2  = 1.46;            
n_Ta2O5 = 2.14;    

hg      = 1;
f       = 0.65;                  
L       = D_period*f;

h_H     = 0.1295;
h_L     = 0.1995;

htop    = 1.294;

hc       = htop - hg;
huplayer = [hc, 0.1003, 0.2687, 0.1353, 0.2000, 0.1878, 0.2226, 0.1212, 0.3479, h_H]*0;

num_pairs     = 20;

d_list        = [repmat([h_L, h_H], 1, num_pairs)];
n_stack_inner = repmat([4, 5], 1, num_pairs);

k0          = nAir*sin(theta*pi/180);

textures{1} = nAir;
textures{2} = n_sub;
textures{3} = {[-L/2, L/2], [nAir, n_SiO2]};

textures{4} = n_SiO2;
textures{5} = n_Ta2O5;

profil = {[1, hg, d_list, 1], [1, 3, n_stack_inner, 2]};

delete(gcp("nocreate"));
parpool('Threads',16)

tic

wvllist = (1000:1100)*1e-3;
