    wavelength = wvllist(wvi);

    parm       = res0(1);
    [aa_te, ~] = res1(wavelength, D_period, textures, nn, k0, parm);
    parm       = res0(-1);
    [aa_tm, ~] = res1(wavelength, D_period, textures, nn, k0, parm);

    ef_te      = res2(aa_te, profil);
    ef_tm      = res2(aa_tm, profil);

    te_f1(wvi)      = ef_te.inc_top_reflected.efficiency{-1};
    tm_f1(wvi)      = ef_tm.inc_top_reflected.efficiency{-1};

    te_0(wvi)       = ef_te.inc_top_reflected.efficiency{0};
    tm_0(wvi)       = ef_tm.inc_top_reflected.efficiency{0};

end

 
output_dir = fullfile(fileparts(mfilename('fullpath')), 'outputs');
