    mkdir(output_dir);
end
save(fullfile(output_dir, 'f065_re1000.mat'), 'wvllist', 'te_f1', 'te_0', 'tm_f1', 'tm_0');
plot(wvllist, te_f1, 'r-', wvllist, tm_f1, 'b-', wvllist, te_0, 'r--', wvllist, tm_0, 'b--')

